#include "text_world.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void) { tw_event_calendar cal; tw_rumor_board board; const tw_world_event *event; const tw_rumor *rumor; memset(&cal,0,sizeof cal); memset(&board,0,sizeof board); assert(tw_event_schedule(&cal,"harvest",7,100,200)==TW_OK); assert(tw_event_schedule(&cal,"harvest",7,100,200)==TW_ERR_DUPLICATE); assert(tw_event_advance(&cal,99)==0); assert(tw_event_advance(&cal,100)==1); event=tw_event_find(&cal,"harvest"); assert(event&&event->state==TW_EVENT_ACTIVE&&event->zone_id==7); assert(tw_event_advance(&cal,200)==1); assert(tw_event_find(&cal,"harvest")->state==TW_EVENT_ENDED); assert(tw_rumor_publish(&board,"dragon","A dragon was seen beyond the old bridge.",1,100,3,5)==TW_OK); assert(tw_rumor_spread(&board,"dragon",2,80)==TW_OK); rumor=tw_rumor_find(&board,"dragon-1"); assert(rumor&&rumor->current_zone==2&&rumor->confidence==80&&rumor->hops_left==2); assert(tw_rumor_advance_day(&board)==0); rumor=tw_rumor_find(&board,"dragon-1"); assert(rumor&&rumor->confidence==72&&rumor->ttl==3); assert(tw_rumor_publish(&board,"bad","invalid",4,101,1,1)==TW_ERR_ARGUMENT); puts("Text-world tests: PASS"); return 0; }
